export const normalizeListItem = (s) => (s ?? "").trim().replace(/\s+/g, " ");
export const normalizeList = (val) => {
    const raw = Array.isArray(val) ? val : [];
    const seen = new Set();
    const out = [];
    for (const v of raw) {
        const n = normalizeListItem(String(v ?? ""));
        if (!n)
            continue;
        const key = n.toLowerCase();
        if (seen.has(key))
            continue;
        seen.add(key);
        out.push(n);
    }
    return out;
};
export const parseOptionalNumber = (raw) => {
    const s = String(raw ?? "").trim();
    if (!s)
        return undefined;
    const n = Number(s);
    return Number.isFinite(n) ? n : undefined;
};
export const parseOptionalInt = (raw) => {
    const n = parseOptionalNumber(raw);
    if (n === undefined)
        return undefined;
    return Math.trunc(n);
};
