import { useCallback } from "react";
export const parseOptionalNumber = (value) => {
    const normalized = String(value ?? "").trim();
    if (!normalized)
        return undefined;
    const parsed = Number(normalized);
    return Number.isFinite(parsed) ? parsed : undefined;
};
export const parseOptionalInteger = (value) => {
    const parsed = parseOptionalNumber(value);
    return parsed === undefined ? undefined : Math.trunc(parsed);
};
export const parseLines = (value) => value
    .split(/\r?\n/)
    .map((item) => item.trim())
    .filter(Boolean);
export const linesToText = (value) => (value ?? []).join("\n");
export const useObjectUpdater = (value, onChange) => useCallback((key, nextValue) => {
    onChange({
        ...value,
        [key]: nextValue,
    });
}, [onChange, value]);
